Rules.InvariantScript:
// Filter and sort the BookingCarCollection based on various criteria
SortByColumns(
    Filter(
        BookingCarCollection,
        
        // Filter by Title using TxtFilterCarname (if TxtFilterCarname is not empty)
        If(
            !IsBlank(TxtFilterCarname_2.Text), 
            StartsWith(Title, TxtFilterCarname_2.Text), 
            true
        ),
        
        // Filter by CarID using TxtFilterCarID (if TxtFilterCarID is not empty)
        If(
            !IsBlank(TxtFilterCarID_2.Text), 
            CarID = Value(TxtFilterCarID_2.Text), 
            true
        ),

        // Filter by BookingStatus (Choice column) using the collection
        (IsBlank(SelectedBookingCarStatus) || 
            CountRows(Filter(SelectedBookingCarStatus, Value = CarStatus.Value)) > 0),
        
        // Filter by CarAdded date range from DatePicker1 to DatePicker1_1
        If(
            !IsBlank(DatePickerDateAddedFrom_2.SelectedDate) && !IsBlank(DatePickerDateAddedTo_2.SelectedDate),
            CarAddedDate >= DatePickerDateAddedFrom_2.SelectedDate && 
            CarAddedDate <= DatePickerDateAddedTo_2.SelectedDate,
            true
        )
    ),
    // Sort by the CarAddedDate in descending order to show the latest added cars first
    "CarAddedDate", 
    SortOrder.Descending
)

UpdateContext({ ShowLoader: true });
Remove('Booking Cars List', ThisItem);
Refresh('Booking Cars List');
UpdateContext({ ShowLoader: false });
ClearCollect(BookingCarCollection, 'Booking Cars List');

