Rules.InvariantScript:
// ✅ Vérifier les champs requis
If(
    IsBlank(Txt_CarName_3.Text) || IsBlank(Txt_CarID_3.Text),
    
    // ❌ Erreur : champs obligatoires manquants
    UpdateContext({ ShowError: true })
,
    // ✅ Champs valides : procéder
    UpdateContext({
        ShowError: false,
        ShowLoader: true
    });

    // ✅ Patch : ajout ou mise à jour
    Set(
        PatchedItem12,
        Patch(
            'Booking Cars List',
            If(IsBlank(varItemToEdit2), Defaults('Booking Cars List'), varItemToEdit2),
            {
                Title: Txt_CarName_3.Text,
                CarID: Value(Txt_CarID_3.Text),
                CarStatus: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                    Value: "Active"
                },
                CarAddedDate: Today()
            }
        )
    );
    // Recharge complètement l’élément patché avec les pièces jointes
Set(varItemToEdit2, LookUp('Booking Cars List', ID = PatchedItem12.ID)),
    // ✅ Soumettre les pièces jointes si le patch a réussi
    If(
        !IsBlank(PatchedItem12) && !IsError(PatchedItem12),
        AttachmentForm_3.LastSubmit.ID = PatchedItem12.ID;
        SubmitForm(AttachmentForm_3);
    );

    // ✅ Nettoyer les champs
    Reset(Txt_CarName_3);
    Reset(Txt_CarID_3);
    Reset(AddAttachment_4);

    // ✅ Mise à jour du contexte
    UpdateContext({
        SuccessMessage: "Booking information successfully saved.",
        ShowLoader: false,
        AddCarPopup: false
    });

    // ✅ Réinitialiser varItemToEditProject
    Set(varItemToEdit2, Blank());

    // ✅ Recharger la collection
    ClearCollect(BookingCarCollection, 'Booking Cars List')
)

If(
    Not(IsBlank(LookUp(SelectedBookingCarStatus, Value = ThisItem.Value))),
    // Item is already in the new collection, so remove it
    Remove(
        SelectedBookingCarStatus,
        LookUp(SelectedBookingCarStatus, Value = ThisItem.Value)
    );
    ,
    // Item is not in the new collection, so add it
    Collect(
        SelectedBookingCarStatus,
        ThisItem
    )
)

If(
    Not(IsBlank(LookUp(SelectedBookingCarStatus, Value = ThisItem.Value))),
    // Item is selected
    If(
        ThisItem.Value = "Active",
        RGBA(48, 194, 27, 1), // Color for "Booked"
        If(
            ThisItem.Value = "Maintenance",
            RGBA(251, 25, 25, 1), // Color for "Cancelled"
            Parent.Fill // Default color if the status is neither "Booked" nor "Cancelled"
        )
    ),
    // Item is not selected
    RGBA(44, 44, 44, 1) // Default color when not selected
)

//Clear All Filter
Reset(TxtFilterCarname_2);           //carname
Reset(TxtFilterCarID_2);            //CarID
Reset(DatePickerDateAddedFrom_2);  //DateAddedFrom
Reset(DatePickerDateAddedTo_2);   //DateAddedTo
Reset(Dropdown1_2);
Refresh('Booking Cars List');
